package mavis

import (
	"context"
	"encoding/json"
	"net/url"
	"regexp"
)

// Agent routes are the leaves cTu reaches in @minimax-ai/code 0.7.8.
// GET /mavis/api/agent/{name} (no further segment) is handled inside
// routeResolvedAgent, and cTu does not call that function unless the path has
// another segment. That info response is not available through this dispatcher.
// createLocalAgent reads name, displayName or display_name, description,
// avatar, persona, systemPrompt or system_prompt, and defaultWorkspaceDir or
// default_workspace_dir. An omitted name is generated by the server. The name,
// when set, must match ^[a-z][a-z0-9_-]*$.

var agentNamePattern = regexp.MustCompile(`^[a-z][a-z0-9_-]*$`)

// LocalAgentCreate is the JSON createLocalAgent reads.
type LocalAgentCreate struct {
	Name                string `json:"name,omitempty"`
	DisplayName         string `json:"displayName,omitempty"`
	Description         string `json:"description,omitempty"`
	Avatar              string `json:"avatar,omitempty"`
	Persona             string `json:"persona,omitempty"`
	SystemPrompt        string `json:"systemPrompt,omitempty"`
	DefaultWorkspaceDir string `json:"defaultWorkspaceDir,omitempty"`
}

// LocalAgentCreated is the 201 body. Other fields stay on Raw.
type LocalAgentCreated struct {
	Name          string          `json:"name"`
	RootSessionID string          `json:"rootSessionId"`
	Raw           json.RawMessage `json:"-"`
}

// CreateLocalAgent calls POST /mavis/api/agent.
func (c *Client) CreateLocalAgent(ctx context.Context, body LocalAgentCreate) (LocalAgentCreated, error) {
	if body.Name != "" && !agentNamePattern.MatchString(body.Name) {
		return LocalAgentCreated{}, errAgentName
	}
	rawBody, err := json.Marshal(body)
	if err != nil {
		return LocalAgentCreated{}, err
	}
	raw, err := c.call(ctx, "POST", "/mavis/api/agent", rawBody)
	if err != nil {
		return LocalAgentCreated{}, err
	}
	var out LocalAgentCreated
	if err := json.Unmarshal(raw, &out); err != nil {
		return LocalAgentCreated{}, err
	}
	out.Raw = raw
	return out, nil
}

// AgentSessionLookupResult is GET /mavis/api/agent/session/{id}.
// session and agent are not a closed schema.
type AgentSessionLookupResult struct {
	Session json.RawMessage `json:"session"`
	Agent   json.RawMessage `json:"agent"`
	Raw     json.RawMessage `json:"-"`
}

// AgentSessionLookup calls GET /mavis/api/agent/session/{id}.
func (c *Client) AgentSessionLookup(ctx context.Context, sessionID string) (AgentSessionLookupResult, error) {
	if sessionID == "" {
		return AgentSessionLookupResult{}, errSessionID
	}
	raw, err := c.get(ctx, "/mavis/api/agent/session/"+url.PathEscape(sessionID))
	if err != nil {
		return AgentSessionLookupResult{}, err
	}
	var out AgentSessionLookupResult
	if err := json.Unmarshal(raw, &out); err != nil {
		return AgentSessionLookupResult{}, err
	}
	out.Raw = raw
	return out, nil
}

// AgentIM is the local fallback for GET and DELETE /mavis/api/agent/{name}/im
// when no channel port is installed. A channel port may add fields; those stay on Raw.
type AgentIM struct {
	Channel        json.RawMessage `json:"channel"`
	ActiveBindings json.RawMessage `json:"activeBindings"`
	LocalRuntime   bool            `json:"localRuntime"`
	OK             bool            `json:"ok"`
	Deleted        bool            `json:"deleted"`
	DeletedCount   int             `json:"deletedCount"`
	Raw            json.RawMessage `json:"-"`
}

// AgentIMStatus calls GET /mavis/api/agent/{name}/im.
func (c *Client) AgentIMStatus(ctx context.Context, agent string) (AgentIM, error) {
	return c.agentIM(ctx, "GET", agent)
}

// DeleteAgentIM calls DELETE /mavis/api/agent/{name}/im.
func (c *Client) DeleteAgentIM(ctx context.Context, agent string) (AgentIM, error) {
	return c.agentIM(ctx, "DELETE", agent)
}

func (c *Client) agentIM(ctx context.Context, method, agent string) (AgentIM, error) {
	raw, err := c.call(ctx, method, agentRoute(agent, "im"), nil)
	if err != nil {
		return AgentIM{}, err
	}
	var out AgentIM
	if err := json.Unmarshal(raw, &out); err != nil {
		return AgentIM{}, err
	}
	out.Raw = raw
	return out, nil
}

