// ReplaceAgentRootSession calls PUT /mavis/api/agent/{name}/session/root.
// The handler requires sessionId or session_id. An empty id is rejected here.
// A legacy agent answers 501. Success is {ok:true}.
func (c *Client) ReplaceAgentRootSession(ctx context.Context, agent, sessionID string) (Ack, error) {
	if sessionID == "" {
		return Ack{}, errSessionID
	}
	body, err := json.Marshal(map[string]string{"sessionId": sessionID})
	if err != nil {
		return Ack{}, err
	}
	return c.ack(ctx, "PUT", agentRoute(agent, "session/root"), body)
}

// AgentSessionCreated is the 201 body from POST /mavis/api/agent/{name}/session.
type AgentSessionCreated struct {
	SessionID string          `json:"sessionId"`
	Session   json.RawMessage `json:"session"`
	Raw       json.RawMessage `json:"-"`
}

// CreateAgentSession calls POST /mavis/api/agent/{name}/session.
// The body is forwarded unchanged. The handler reads title, purpose,
// parentSessionId, workspaceDir or workspace_dir, visibility, and model, and
// rejects an opencode runtime. Unknown keys are the server's to ignore.
func (c *Client) CreateAgentSession(ctx context.Context, agent string, body json.RawMessage) (AgentSessionCreated, error) {
	raw, err := c.call(ctx, "POST", agentRoute(agent, "session"), body)
	if err != nil {
		return AgentSessionCreated{}, err
	}
	var out AgentSessionCreated
	if err := json.Unmarshal(raw, &out); err != nil {
		return AgentSessionCreated{}, err
	}
	out.Raw = raw
	return out, nil
}

// RequestAgentCompaction calls POST /mavis/api/agent/{name}/session/{id}/request-compaction.
// The body is the JSON the handler forwards. Its schema was not recovered.
func (c *Client) RequestAgentCompaction(ctx context.Context, agent, sessionID string, body json.RawMessage) (RawDocument, error) {
	if sessionID == "" {
		return RawDocument{}, errSessionID
	}
	return c.callDoc(ctx, "POST", agentRoute(agent, "session/"+url.PathEscape(sessionID)+"/request-compaction"), body)
}

// AgentAvatar calls GET /mavis/api/agent/{name}/identity/avatar.
// A hit is raw bytes with the handler's Content-Type, not a JSON document.
func (c *Client) AgentAvatar(ctx context.Context, agent string) ([]byte, string, error) {
	resp, err := c.d.RawCall(ctx, "GET", agentRoute(agent, "identity/avatar"), map[string]string{"accept": "*/*"}, nil)
	if err != nil {
		return nil, "", err
	}
	if err := resp.StatusError("GET agent avatar"); err != nil {
		return nil, "", err
	}
	ctype := ""
	for key, value := range resp.Headers {
		if key == "Content-Type" || key == "content-type" {
			ctype = value
		}
	}
	return append([]byte(nil), resp.Body...), ctype, nil
}

func agentRoute(agent string, rest string) string {
	return "/mavis/api/agent/" + url.PathEscape(agent) + "/" + rest
}
